int Length_LinkList1(LinkList L)    /*当链表带头节点时*/
{    LNode *p=L;    /*p指向头节点*/
    int i=0;    /*设计数器变量i*/
    while(p->next)
    {    p=p->next;i++; }    /*p指针依次后移*/
    return i;
}

int Length_LinkList2(LinkList L)    /*当链表不带头节点时*/
{    LNode *p=L;
    int i;    /*设计数器变量 i*/
    if(p==NULL) return 0;    /*为空表，返回 0*/
    i=1;    /*为非空表，p 指向最前面的节点*/
    while(p->next)
    {    p=p->next;i++;    }
    return i;
}
